/* Signature Xhosa Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Thandolwethu": "From thanda (love) + -lwethu (our): 'our beloved'.", "Siphamandla": "From sipho (gift) + mandla (strength): 'gift of strength'.", "Nomvulazana": "From mvula (rain) + -azana (diminutive feminine): 'little rain princess'.", "Lungelani": "From lunga (be good) + -elani (for you all): 'be good for all'.", "Bhekizwe": "From bheka (watch, be on guard) + izwe (land): 'guardian of the land'.", "Jabulisile": "From jabula (rejoice) + -isile: 'she has brought joy'.", "Thandabantu": "From thanda (love) + bantu (people): Signature clan-style surname, 'lover of the people'.", "Mvulazwe": "From mvula (rain) + izwe (land): Signature surname, 'rain of the land'.", "Lungelo": "From lunga (be right): Signature surname, 'rightness'.", "Siphokazi": "From sipho (gift) + -kazi (feminine great): Signature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Thandolwethu';
console.log(lookup(q));

